        {
          "kind": "metric",
          "sql": "SELECT time, metric, round(value,3) v FROM abnormal_metrics WHERE service_name='ts-seat-service' AND metric='container.cpu.usage' ORDER BY time",
          "claim": "Seat-service container CPU climbed from about 0.3 cores to a ~5.0-core ceiling from 01:55:49 to 01:57:14, then fell back."
        },
        {
          "kind": "metric",
          "sql": "WITH x AS (SELECT 'ab' per, service_name, metric, value FROM abnormal_metrics UNION ALL SELECT 'no', service_name, metric, value FROM normal_metrics) SELECT per, round(avg(value),3) avg_cpu FROM x WHERE service_name='ts-seat-service' AND metric='container.cpu.usage' GROUP BY per",
          "claim": "Seat-service average container CPU rose from about 0.28 cores in normal to about 2.0 cores in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "WITH x AS (SELECT 'no' per, * FROM normal_traces UNION ALL SELECT 'ab', * FROM abnormal_traces) SELECT per, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM x WHERE service_name='ts-seat-service' AND span_name='POST /api/v1/seatservice/seats/left_tickets' GROUP BY per",
          "claim": "Seat left_tickets p95 rose from about 17 ms to 26 ms, and its span count fell, while callers timed out."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name<>c.service_name AND p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND c.service_name IN ('ts-travel2-service','ts-travel-service','ts-seat-service') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Travel2 and travel make many seat calls; travel2 has client spans that error after about 3.5 s with no traced callee response."
        }
      ]
    }
  ],
  "propagation": [
